'use strict';
// Disposable synthetic fixture only. Callers own PostgreSQL/connector lifetime,
// native snapshot import, finite deadlines and exact actor cleanup. Creating a
// fixture never discovers or drops a pre-existing schema or replication slot.
const {randomBytes}=require('node:crypto');
const state=require('../../lib/storage/clinical-stream-state');
const sql=require('../../lib/storage/clinical-stream-sql');
const journal=require('../../lib/storage/storage-event-journal');
const work=require('../../lib/pgstream/work-state');
const DEFAULT_TENANTS=['11111111-1111-4111-8111-111111111111','22222222-2222-4222-8222-222222222222'];
const UUID=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
const snapshotDigest='a'.repeat(64),completedDigest='b'.repeat(64);
async function create({admin,pool,prefix='synthetic_cohort_'+randomBytes(4).toString('hex'),tenants=DEFAULT_TENANTS,maxRows=256,maxBytes=1048576}={}){
 if(!admin||typeof admin.query!=='function'||!pool||typeof pool.connect!=='function'||! /^synthetic_[a-z0-9_]{1,30}$/.test(prefix)||!Array.isArray(tenants)||!tenants.length||tenants.some(t=>!UUID.test(t))||new Set(tenants).size!==tenants.length)throw new TypeError('Explicit disposable clinical cohort fixture binding required');
 const schemas=state.DOMAINS.map(domain=>prefix+'_'+domain),workSchema=prefix+'_work',table=workSchema+'.tenant_consumer_checkpoint',consumer='evaluator-native-cohort',created=[];
 const domains=Object.fromEntries(state.DOMAINS.map((domain,i)=>[domain,schemas[i]+'.'+domain]));
 const routes=Object.entries(domains).map(([domain,relation])=>({schema:relation.split('.')[0],table:domain,domain}));
 const queries=[];let closed=false;
 async function query(client,text,values){queries.push({text,bytes:Buffer.byteLength(JSON.stringify(values??[]))});return client.query(text,values);}
 try{
  // CREATE SCHEMA fails on a collision, preserving another run's resources.
  for(const schema of [...schemas,workSchema]){await admin.query('CREATE SCHEMA '+schema);created.push(schema);}
  for(const [domain,relation]of Object.entries(domains))await admin.query('CREATE TABLE '+relation+' (tenant_id uuid NOT NULL,id_kind text NOT NULL,"_id" text NOT NULL,doc jsonb NOT NULL,insertion_ordinal bigint GENERATED BY DEFAULT AS IDENTITY,storage_bytes bigint NOT NULL,PRIMARY KEY(tenant_id,id_kind,"_id")); ALTER TABLE '+relation+' REPLICA IDENTITY FULL');
  await admin.query('CREATE TABLE '+table+' (tenant_id uuid NOT NULL,consumer text NOT NULL,checkpoint bigint NOT NULL DEFAULT 0,contract_digest text NOT NULL,projection jsonb,work_version integer NOT NULL DEFAULT 2,work_observed bigint[] NOT NULL DEFAULT ARRAY[NULL,NULL,NULL,NULL,NULL,NULL]::bigint[],work_completed bigint[] NOT NULL DEFAULT ARRAY[NULL,NULL,NULL,NULL,NULL,NULL]::bigint[],work_observed_at bigint[] NOT NULL DEFAULT ARRAY[NULL,NULL,NULL,NULL,NULL,NULL]::bigint[],work_pending_at bigint,work_due_at bigint,work_completed_at bigint,work_enabled boolean NOT NULL DEFAULT true,work_activity_enabled boolean NOT NULL DEFAULT true,work_lifecycle_enabled boolean NOT NULL DEFAULT true,delivery_revision bigint NOT NULL DEFAULT 0,delivery_ack_revision bigint NOT NULL DEFAULT 0,output_identity text,output_digest text,output_revision bigint NOT NULL DEFAULT 0,output_restore_generation bigint,PRIMARY KEY(tenant_id,consumer))');
  for(const tenant of tenants){
   await admin.query('INSERT INTO '+table+' (tenant_id,consumer,contract_digest,projection) VALUES ($1,$2,$3,$4::jsonb),($1,$5,$6,$7::jsonb)',[tenant,consumer,snapshotDigest,JSON.stringify([state.empty(),journal.empty()]),consumer+'-completed',completedDigest,JSON.stringify([{kind:'evaluator-work-v2',output:null}])]);
  }
 }catch(error){for(const schema of created.reverse())await admin.query('DROP SCHEMA '+schema+' CASCADE');throw error;}
 function sqlOptions(expectedSource,{generation='fixture:1',assertFence=async()=>generation,lockKey=()=>'124252342164564'}={}){
  return {pool,observeBackend:async()=>{},table,consumer,snapshotDigest,completedConsumer:consumer+'-completed',completedDigest,routes,expectedSource,assertFence,lockKey,maxRows,maxBytes,maxTransactionRows:1024,maxTransactionBytes:4194304};
 }
 async function seed(client,tenant,boundary,{policy}={}){
  if(!tenants.includes(tenant))throw new TypeError('Unknown fixture tenant');
  // The caller must already have imported a native snapshot, before any query.
  // This helper deliberately issues neither BEGIN nor COMMIT.
  const saved=(await query(client,'SELECT checkpoint,projection FROM '+table+' WHERE tenant_id=$1 AND consumer=$2 FOR UPDATE',[tenant,consumer])).rows[0];
  if(!saved)throw new Error('NATIVE_FIXTURE_NOT_PROVISIONED');
  const rows=[];
  for(const [domain,relation]of Object.entries(domains)){
   const source=(await query(client,'SELECT id_kind,doc,insertion_ordinal,storage_bytes FROM '+relation+' WHERE tenant_id=$1 ORDER BY insertion_ordinal',[tenant])).rows;
   rows.push(...source.map(row=>({domain,document:require('../../lib/storage/postgres-identity').decodeDocument(row),ordinal:Number(row.insertion_ordinal),storageBytes:Number(row.storage_bytes)})));
  }
  const previous=saved.projection?.[0]?.kind===state.KIND?saved.projection[0]:null,floor=Number(saved.checkpoint)+1;
  const next=state.bootstrap(previous,{checkpoint:floor,signature:{stamp:floor,deleted:previous?.deleted??0},stream:boundary,rows,...(policy?{policy}:{})},{maxRows,maxBytes});
  const same=previous?.stream&&state.sameSource(previous.stream.source_identity,boundary.source_identity)&&previous.stream.generation===boundary.generation;
  const tail=same?journal.validate(saved.projection?.[1]):journal.reset(saved.projection?.[1]);
  await query(client,'UPDATE '+table+' SET checkpoint=$3,projection=$4::jsonb,contract_digest=$5 WHERE tenant_id=$1 AND consumer=$2',[tenant,consumer,floor,JSON.stringify([next,tail]),snapshotDigest]);
  await work.observeInTransaction({client,table,consumer:consumer+'-completed',contractDigest:completedDigest,observations:[{tenant,observed:{bootstrap:String(floor)}}]});
  return next;
 }
 async function insert(tenant,domain,document,{idKind='string'}={}){
  if(!tenants.includes(tenant)||!domains[domain]||typeof document?._id!=='string')throw new TypeError('Explicit synthetic source row required');
  return query(admin,'INSERT INTO '+domains[domain]+" (tenant_id,id_kind,\"_id\",doc,storage_bytes) VALUES ($1,$2,$3,$4::jsonb,pg_column_size($4::jsonb)) RETURNING insertion_ordinal::text AS ordinal",[tenant,idKind,document._id,JSON.stringify(document)]);
 }
 async function read(tenant){return (await admin.query('SELECT checkpoint::text,projection,work_observed,work_completed,delivery_revision::text,delivery_ack_revision::text FROM '+table+' WHERE tenant_id=$1 AND consumer=$2',[tenant,consumer])).rows[0];}
 async function output(tenant){return (await admin.query('SELECT work_observed,work_completed,work_pending_at,delivery_revision::text,delivery_ack_revision::text FROM '+table+' WHERE tenant_id=$1 AND consumer=$2',[tenant,consumer+'-completed'])).rows[0];}
 return Object.freeze({prefix,tenants,table,consumer,snapshotDigest,completedDigest,domains,routes,queries,sqlOptions,seed,insert,read,output,accept:(envelope,options)=>sql.acceptTransaction({...options,envelope}),async close(){if(closed)return;closed=true;for(const schema of created.slice().reverse())await admin.query('DROP SCHEMA '+schema+' CASCADE');}});
}
module.exports={create};
